window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-22891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεκράκτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2106 na letra κ · nº geral 22891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que grita; vociferador. 〈κέκραγα〉</p></section></article>\n<article id=\"entry-dgp-22892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέκραμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2107 na letra κ · nº geral 22892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κεράννυμι.</p></section></article>\n<article id=\"entry-dgp-22893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεκραμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 2108 na letra κ · nº geral 22893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com medida; na medida certa 2 com perfeita arte. 〈κεράννυμι〉</p></section></article>\n<article id=\"entry-dgp-22894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέκρανται</h1><div class=\"entry-meta\"><span>DGP · ordem 2109 na letra κ · nº geral 22894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. perf. pas. ép. de κραίνω.</p></section></article>\n<article id=\"entry-dgp-22895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεκράξομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2110 na letra κ · nº geral 22895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κράζω.</p></section></article>\n<article id=\"entry-dgp-22896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέκριγα</h1><div class=\"entry-meta\"><span>DGP · ordem 2111 na letra κ · nº geral 22896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κρίζω.</p></section></article>\n<article id=\"entry-dgp-22897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέκρικα</h1><div class=\"entry-meta\"><span>DGP · ordem 2112 na letra κ · nº geral 22897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κρίνω.</p></section></article>\n<article id=\"entry-dgp-22898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεκριμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 2113 na letra κ · nº geral 22898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com conhecimento de causa; com discernimento; judiciosamente. 〈κρίνω〉</p></section></article>\n<article id=\"entry-dgp-22899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέκρυμμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2114 na letra κ · nº geral 22899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de κρύπτω.</p></section></article>\n<article id=\"entry-dgp-22900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κεκροπία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2115 na letra κ · nº geral 22900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Κεκρόπιος.</p></section></article>\n<article id=\"entry-dgp-22901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κεκροπίδης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2116 na letra κ · nº geral 22901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 descendente de Cécrops, i.e., ateniense ♦ οἱ Κεκροπίδαι 2 os atenienses. 〈Κέκροψ〉</p></section></article>\n<article id=\"entry-dgp-22902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κεκρόπιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2117 na letra κ · nº geral 22902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Cécrops: Κεκροπία πέτρα eur. a rocha de Cécrops, i.e., a cidadela de Atenas, Κεκροπία χθών eur. a terra de Cécrops, i.e., a Ática ♦ οἱ Κεκρόπιοι 2 os descendentes de Cécrops, i.e., os atenienses ♦ ἡ Κεκροπία 3 Cecrópia, n. da cidadela de Atenas, construída por Cécrops 4 Atenas. 〈Κέκροψ〉</p></section></article>\n<article id=\"entry-dgp-22903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κεκροπίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2118 na letra κ · nº geral 22903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de Cécrops. 〈Κέκροψ〉</p></section></article>\n<article id=\"entry-dgp-22904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κέκροψ, οπος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2119 na letra κ · nº geral 22904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Cécrops, o primeiro rei da Ática, fundador de Atenas 2 Cécrops, filho e sucessor de Erecteu.</p></section></article>\n<article id=\"entry-dgp-22905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέκρυφα</h1><div class=\"entry-meta\"><span>DGP · ordem 2120 na letra κ · nº geral 22905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κρύπτω.</p></section></article>\n<article id=\"entry-dgp-22906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεκρύφαλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2121 na letra κ · nº geral 22906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 véu ou lenço com que as mulheres cobriam a cabeça 2 cavidade ou fundo de uma rede de caça 3 segundo estômago dos ruminantes 4 testeira de cavalo. 〈κορυφή〉</p></section></article>\n<article id=\"entry-dgp-22907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεκρύφαται</h1><div class=\"entry-meta\"><span>DGP · ordem 2122 na letra κ · nº geral 22907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. jôn. perf. pas. de κρύπτω.</p></section></article>\n<article id=\"entry-dgp-22908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεκτήμην</h1><div class=\"entry-meta\"><span>DGP · ordem 2123 na letra κ · nº geral 22908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">m.-q.-perf. poét. de κτάομαι.</p></section></article>\n<article id=\"entry-dgp-22909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεκύθωσι</h1><div class=\"entry-meta\"><span>DGP · ordem 2124 na letra κ · nº geral 22909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. subj. aor.2 poét. de κεύθω.</p></section></article>\n<article id=\"entry-dgp-22910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέκυφα</h1><div class=\"entry-meta\"><span>DGP · ordem 2125 na letra κ · nº geral 22910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κύπτω.</p></section></article>\n<article id=\"entry-dgp-22911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελαδεινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2126 na letra κ · nº geral 22911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ruidoso; sonoro; ressoante ♦ ἡ κελαδεινή 2 a ruidosa; a barulhenta, ref. a Ártemis, por causa do barulho da caça. 〈κέλαδος〉</p></section></article>\n<article id=\"entry-dgp-22912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελαδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2127 na letra κ · nº geral 22912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐκελάδουν, fut. κελαδήσω e κελαδή­σομαι, aor. poét. κελάδησα, perf. desus.) 1 intr. fazer barulho; ressoar; soar 2 fazer ressoar (canto, grito), ac. 3 gabar; louvar; celebrar ♦ méd. 4 celebrar. 〈κέλαδος〉</p></section></article>\n<article id=\"entry-dgp-22913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελάδημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2128 na letra κ · nº geral 22913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barulho ressonante; rumor; som. 〈κέλαδος〉</p></section></article>\n<article id=\"entry-dgp-22914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλαδος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2129 na letra κ · nº geral 22914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 barulho estrondoso; grito; clamor 2 canto; acordes 3 voz nítida, sonora. 〈κράζω〉</p></section></article>\n<article id=\"entry-dgp-22915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελάδω</h1><div class=\"entry-meta\"><span>DGP · ordem 2130 na letra κ · nº geral 22915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) ressoar; part. καλάδων sonoro; ressoante (mar, vento). 〈κέλαδος〉</p></section></article>\n<article id=\"entry-dgp-22916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελαινεφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2131 na letra κ · nº geral 22916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de nuvens negras 2 negro; sombrio. 〈κελαινός, νέφος〉</p></section></article>\n<article id=\"entry-dgp-22917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελαινόβρωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2132 na letra κ · nº geral 22917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">negro e corroído. 〈κελαινός, βι­βρώσκω〉</p></section></article>\n<article id=\"entry-dgp-22918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελαινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2133 na letra κ · nº geral 22918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 negro; sombrio 2 manchado de sangue 3 obscuro.</p></section></article>\n<article id=\"entry-dgp-22919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελαινόφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2134 na letra κ · nº geral 22919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος de espírito sombrio; de alma negra; impenetrável. 〈κελαινός, φρήν〉</p></section></article>\n<article id=\"entry-dgp-22920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελαινόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2135 na letra κ · nº geral 22920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar-se negro, sobrio. 〈κελαινός〉</p></section></article>\n<article id=\"entry-dgp-22921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελαινώπας, α</h1><div class=\"entry-meta\"><span>DGP · ordem 2136 na letra κ · nº geral 22921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) dór. de aspecto sombrio; impenetrável. 〈κελαινός, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-22922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελαρύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2137 na letra κ · nº geral 22922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ép. κελάρυζον) 1 intr. brotar ou escorrer borbulhando: ἀπ’ ἕλκεος ἀργαλέοιο αἷμα μέλαν κελάρυζε hom. da horrível ferida escorria o sangue negro 2 verter ou fazer escorrer borbulhando. 〈κέλαδος, ῥέω〉</p></section></article>\n<article id=\"entry-dgp-22923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλεαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2138 na letra κ · nº geral 22923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. pres. ép. de κέλομαι.</p></section></article>\n<article id=\"entry-dgp-22924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλευθα</h1><div class=\"entry-meta\"><span>DGP · ordem 2139 na letra κ · nº geral 22924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κέλευθος.</p></section></article>\n<article id=\"entry-dgp-22925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελευθοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2140 na letra κ · nº geral 22925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que abre ou prepara o caminho. 〈κέλευθος, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-22926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλευθος, ου (ἡ</h1><div class=\"entry-meta\"><span>DGP · ordem 2141 na letra κ · nº geral 22926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e τό) pl. κέλευθοι e κέλευθα 1 estrada; caminho; rota: πόθεν πλεῖθ’ ὑγρὰ κέλευθα; hom. de onde chegais pelos caminhos úmidos?, ἰχθυόεντα κέλευθα hom. rotas piscosas, i.e., o mar, κέλευθα ἀστέρων eur. as rotas dos astros, κέλευθοι βίου eur. os rumos da vida 2 viagem por terra ou por mar: μέτρα κελεύθου hom. a extensão da viagem 3 expedição militar 4 maneira de andar; passo.</p></section></article>\n<article id=\"entry-dgp-22927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελεύομεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2142 na letra κ · nº geral 22927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª pl. pres. ind. ou subj. ép., κέλευον impf. poét., κελευσέμεναι inf. fut. ép., de κελεύω.</p></section></article>\n<article id=\"entry-dgp-22928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλευσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2143 na letra κ · nº geral 22928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de comandar; comando; ordem. 〈κελεύω〉</p></section></article>\n<article id=\"entry-dgp-22929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλευσμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2144 na letra κ · nº geral 22929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ordem; comando: ἀπὸ ἑνὸς κελεύσματος ἐμβοᾶν tuc. todos a um só comando 2 canto cadenciado do chefe dos remadores, para regular o movimento dos remos 3 exortação; encorajamento (para animais) 4 apelo; grito. 〈κελεύω〉</p></section></article>\n<article id=\"entry-dgp-22930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελευσμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2145 na letra κ · nº geral 22930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ordem; comando. 〈κελεύω〉</p></section></article>\n<article id=\"entry-dgp-22931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελευσμοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2146 na letra κ · nº geral 22931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = κελευσμός.</p></section></article>\n<article id=\"entry-dgp-22932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελευστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2147 na letra κ · nº geral 22932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 chefe dos remadores, que marca a cadência dos remos; ritmista 2 arauto. 〈κελεύω〉</p></section></article>\n<article id=\"entry-dgp-22933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελευστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2148 na letra κ · nº geral 22933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que diz respeito ao comando 2 que diz respeito à exortação ♦ ἡ κελευστική 3 arte de exortar, de comandar. 〈κελευστός〉</p></section></article>\n<article id=\"entry-dgp-22934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελευστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2149 na letra κ · nº geral 22934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que recebe uma ordem; comandado. 〈κελεύω〉</p></section></article>\n<article id=\"entry-dgp-22935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελευτιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2150 na letra κ · nº geral 22935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres. ép. κελευτιόων) impelir vivamente; ordenar; exortar. 〈κελεύω〉</p></section></article>\n<article id=\"entry-dgp-22936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2151 na letra κ · nº geral 22936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κελεύσω, aor. ἐκέλευσα, perf. κεκέλευκα; pas. fut. rec. κελευσθήσομαι, aor. ἐκελεύσθην, perf. κεκέλευσμαι) 1 pôr em movimento; impelir; excitar: τοὺς ἵππους μάστιγι κελ. hom. impelir os cavalos com um chicote 2 pressionar pela palavra; excitar; exortar alguém, dat.: κελ. ἀλλήλοισι hom. encorajar-se mutuamente 3 ordenar; comandar; exortar alguém, dat. ou ac., a algo, ac. ou inf.: ἀμφιπόλοισι περικλυτὰ ἔργα κέλευε hom. ordenava magníficos trabalhos às servas, ὁ κηρύκεσσι κέλευσε κηρύσσειν ἀγορήνδε hom. ordenou aos arautos que convocassem para a assembléia, τί με ταῦτα κελεύεις; hom. por que me ordenas isso? τοὺς ἕνδεκα ἐπί Θηραμένην xen. ordenar aos Onze que prendam Terâmene, εἰ μὴ θυμὸς κελεύοι hom. a menos que meu coração me ordene, ὥς με κελεύεις hom. como me ordenas, σιγᾶν κελεύω sóf. ordeno que se cale, εἰ σύ κελεύεις hom. se tu ordenas 4 exprimir um desejo; pedir com insistência a alguém, gen., algo, inf.: υἱὸς μὲν δή τοι λέλυται, γέρον, ὡς ἐκέλευες hom. teu filho está entregue a ti, velho, como pedias, κελεύοντες σφίσι τὸν Ἀστύοχον βοηθεῖν tuc. pedindo que Astíoco os socorresse 5 Náut. marcar a cadência para regular o movimento dos remos ♦ pas. 6 receber uma ordem: πρὶν κελευσθῆναι ὑπὸ τοῦ θεοῦ xen. antes de receber uma ordem do deus, οὐδὲν κελευόμενοι ποιήσειν tuc. não tendo ordem de fazer nada, τὸ κελευόμενον a ordem, τὰ κεκευόμενα as ordens dadas.</p></section></article>\n<article id=\"entry-dgp-22937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλης, ητος</h1><div class=\"entry-meta\"><span>DGP · ordem 2152 na letra κ · nº geral 22937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 de corrida; corredor (cavalo) ♦ ὁ κέ­λης 2 cavalo de boa andadura 3 cavalo de corrida 4 pequeno navio ligeiro com um só banco de remadores.</p></section></article>\n<article id=\"entry-dgp-22938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2153 na letra κ · nº geral 22938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κέλομαι.</p></section></article>\n<article id=\"entry-dgp-22939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελητίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2154 na letra κ · nº geral 22939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">montar a cavalo; cavalgar. 〈κέλης〉</p></section></article>\n<article id=\"entry-dgp-22940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελήτιον ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2155 na letra κ · nº geral 22940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequena chalupa. 〈κέλης〉</p></section></article>\n<article id=\"entry-dgp-22941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 2156 na letra κ · nº geral 22941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κέλσω, aor. ἔκελσα) 1 impelir para a terra; fazer aportar: κ. νῆα hom. fazer aportar um navio, Ἄργει κ. πόδα eur. fazer seus passos chegarem a Argos, chegar a Argos 2 intr. (equipagem, navio) aportar em, ac. ou πρός, ἐπί ou ἐς e ac. 3 chegar a um porto de refúgio (depois de provações): πᾷ κέλσω; eur. por onde encontrarei um porto de refúgio?</p></section></article>\n<article id=\"entry-dgp-22942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2157 na letra κ · nº geral 22942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κελήσομαι, aor.1 ἐκελησάμην, aor.2 ép. ἐκεκλόμην ou κεκλόμην) 1 impelir com força; pressionar: ἰαίνετο κηρὸς, ἐπεὶ κέλετο μεγάλη ἲς καὶ αὐγὴ ἡλίου hom. a cera derretia pois a pressionava a grande força e luz do sol 2 pressionar pela palavra; ordenar; exortar; encorajar alguém, ac. ou dat., a algo, inf. ou ac.: κέλεται δέ με θυμός hom. o coração me impele [a dizer], οἱ δ’ ἐγρηγόρθασι φυλασσέμεναί τε κέλονται ἀλλήλοις hom. e eles, despertos, exortam-se mutuamente para montar guarda, ἀλλ’ ἐς μὲν Μενέλαον ἐγὼ κέλομαι καὶ ἄνωγα ἐλθεῖν hom. mas encorajo e exorto que vás à casa de Menelau, κέλομαι γὰρ ἔγωγε hom. pois quanto a mim, encorajo, i.e., dou meu apoio, κ. μακρὸν ἀΰσας hom. exortar aos gritos, κέλεαι γάρ hom. pois ordenas 3 chamar 4 chamar em socorro; invocar 5 chamar pelo nome.</p></section></article>\n<article id=\"entry-dgp-22943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κέλται, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2158 na letra κ · nº geral 22943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Celtas, povo da antiga Gália. 〈Κελτός〉</p></section></article>\n<article id=\"entry-dgp-22944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2159 na letra κ · nº geral 22944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dos celtas; céltico; gálico ♦ ἡ Κελτική 2 a Gália. 〈Κέλται〉</p></section></article>\n<article id=\"entry-dgp-22945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κελτιστί</h1><div class=\"entry-meta\"><span>DGP · ordem 2160 na letra κ · nº geral 22945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 à maneira dos celtas 2 em língua celta. 〈Κέλται〉</p></section></article>\n<article id=\"entry-dgp-22946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κελτός, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 2161 na letra κ · nº geral 22946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 celta 2 céltico ♦ οἱ Κελτοί 3 os celtas.</p></section></article>\n<article id=\"entry-dgp-22947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέλυφος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2162 na letra κ · nº geral 22947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 invólucro; membrana 2 casca ou pele de fruta 3 cápsula; casulo de inseto 4 casca ou carapaça de crustáceos 5 casca de ovo 6 invólucro da alma, ref. ao corpo 7 com. carcaça: ἀντωμοσιῶν κελύφη ar. carcaças de chicanas, ref. a juízes velhos 8 cavidade dos olhos 9 abrigo. 〈καλύπτω〉</p></section></article>\n<article id=\"entry-dgp-22948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεμάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2163 na letra κ · nº geral 22948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">corça nova; filhote da corça.</p></section></article>\n<article id=\"entry-dgp-22949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2164 na letra κ · nº geral 22949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">covil de animal selvagem.</p></section></article>\n<article id=\"entry-dgp-22950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέν</h1><div class=\"entry-meta\"><span>DGP · ordem 2165 na letra κ · nº geral 22950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κέ.</p></section></article>\n<article id=\"entry-dgp-22951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεναγγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2166 na letra κ · nº geral 22951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que causa a fome; esfomeante. 〈κενός, ἄγγος〉</p></section></article>\n<article id=\"entry-dgp-22952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενανδρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2167 na letra κ · nº geral 22952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">despovoação. 〈κένανδρος〉</p></section></article>\n<article id=\"entry-dgp-22953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κένανδρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2168 na letra κ · nº geral 22953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">privado de homens; despovoado; deserto. 〈κενός, ἀνήρ〉</p></section></article>\n<article id=\"entry-dgp-22954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεναυχής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2169 na letra κ · nº geral 22954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vaidoso. 〈κενός, αὐχή〉</p></section></article>\n<article id=\"entry-dgp-22955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενέβρειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2170 na letra κ · nº geral 22955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de animal morto ♦ τὰ κενέβρεια 2 animal morto em decomposição; carniça.</p></section></article>\n<article id=\"entry-dgp-22956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενεμβατέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2171 na letra κ · nº geral 22956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (pássaro) caminhar ou mover-se no vazio 2 pôr o pé em falso 3 Medic. (sonda) mergulhar em uma cavidade 4 apoiar-se no vazio; não ter base 5 levar uma vida frívola. 〈κενός, ἐμβατέω〉</p></section></article>\n<article id=\"entry-dgp-22957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενεός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2172 na letra κ · nº geral 22957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e ép. = κενός.</p></section></article>\n<article id=\"entry-dgp-22958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενεών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2173 na letra κ · nº geral 22958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 oco entre as costas e os quadris; cintura 2 cavidade; espaço vazio: κενεῶνες οὐράνιοι ant. espaços celestes. 〈κενεός〉</p></section></article>\n<article id=\"entry-dgp-22959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενοδοξία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2174 na letra κ · nº geral 22959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inclinação para a vanglória; vaidade; presunção. 〈κενόδοξος〉</p></section></article>\n<article id=\"entry-dgp-22960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενόδοξος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2175 na letra κ · nº geral 22960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vaidoso; presunçoso. 〈κενός, δόξα〉</p></section></article>\n<article id=\"entry-dgp-22961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενοκοπέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2176 na letra κ · nº geral 22961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dar-se a uma fadiga inútil; cansar-se em vão. 〈κενός, κόπος〉</p></section></article>\n<article id=\"entry-dgp-22962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2177 na letra κ · nº geral 22962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">palavreado inútil; discurso vazio.</p></section></article>\n<article id=\"entry-dgp-22963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενός,</h1><div class=\"entry-meta\"><span>DGP · ordem 2178 na letra κ · nº geral 22963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ép. κενεός e κεινός, ή, όν 1 vazio: κεινῇσι χερσί her. de mãos vazias, κενῇ τῇ κοιλίᾳ ar. de ventre vazio, κενεὸν νέεσθαι hom. voltar de mãos vazias, κενὴν κατηγορεῖν artt. denunciar um ausente 2 vazio de; privado de; destituído de, gen.: κενὸς πάντων xen. vazio de tudo, inteiramente vazio, κενὸν δένδρων πεδίον plat. planície sem árvores, κ. φρονέσεως plat. destituído de prudência 3 privado de forças; debilitado; esgotado (pessoa): ὑπ’ ἄσθματος κενοί ésql. debilitados pela respiração difícil, i.e., exaustos 4 privado do que lhe é próprio ou habitual: σῶμα κενόν plut. corpo descarnado, λέαινα κενή sóf. leoa privada do leão, i.e., desprotegida, Mil. κεναὶ χῶραι ésqn. lugares sem guarnição 5 vazio; sem fundamento; frívolo; fútil (voto, esperança); vão: κενὰ εὔγματα hom. preces vãs, δὶα ou κατὰ κενῆς, κατὰ κενοῦ, ἐν κενοῖς, εἰς κενόν ou εἰς τὸ κένον em vão, sem fundamento ♦ τὸ κενός 6 o vazio.</p></section></article>\n<article id=\"entry-dgp-22964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενόσπουδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2179 na letra κ · nº geral 22964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se dedica a futilidades 2 sem valor; fútil. 〈κενός, σπουδή〉</p></section></article>\n<article id=\"entry-dgp-22965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενοσπούδως</h1><div class=\"entry-meta\"><span>DGP · ordem 2180 na letra κ · nº geral 22965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com esforços inúteis; com busca vã.</p></section></article>\n<article id=\"entry-dgp-22966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενοταφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2181 na letra κ · nº geral 22966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">erguer um túmulo vazio a, ac.; honrar com um cenotáfio: κ. τὸν βίον plut. tornar sua vida um túmulo vazio. 〈κενός, τάφος1〉</p></section></article>\n<article id=\"entry-dgp-22967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2182 na letra κ · nº geral 22967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o vazio; o vácuo 2 vaidade 3 crist. o esvaziar-se; a humilhação. 〈κενός〉</p></section></article>\n<article id=\"entry-dgp-22968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενοφροσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2183 na letra κ · nº geral 22968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">frivolidade de espírito; vaidade. 〈κενόφρων〉</p></section></article>\n<article id=\"entry-dgp-22969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενόφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2184 na letra κ · nº geral 22969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος de espírito vazio; frívolo. 〈κενός, φρήν〉</p></section></article>\n<article id=\"entry-dgp-22970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενοφωνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2185 na letra κ · nº geral 22970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. tagarelice; conversa fiada, vã. 〈κενός, φωνή〉</p></section></article>\n<article id=\"entry-dgp-22971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2186 na letra κ · nº geral 22971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κενώσω, aor. ἐκένωσα, perf. κεκένωκα) 1 tornar vazio, desguarnecido; esvaziar: ἀνδρῶν πόλιν κ. ésql. desguarnecer de homens uma cidade 2 deixar vazio um lugar; abandonar: κ. βωμόν eur. abandonar um altar 3 tornar vazio; enfraquecer; esgotar; reduzir a nada 4 fazer sair; expelir; evacuar; expurgar: κ. αἷμα luc. esgotar o sangue, κ. φάρμακον jâmbl. expelir um veneno 5 gastar; despender; esgotar: εἴς με κένωσον πᾶν σὺ βέλος ant. esgota todas as flechas contra mim, πάντα τά ὄντα εἰς τούς πένητας κ. d.cris. gastar todas suas posses com os pobres ♦ pas. 6 (casa) ser esvaziado 7 ser desguarnecido: κεκενουμένου τοῦ τείχεος πάντων her. tendo sido o muro desnudado de tudo que o guarnecia 8 ser reduzido a nada. 〈κενός〉</p></section></article>\n<article id=\"entry-dgp-22972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κένσαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2187 na letra κ · nº geral 22972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. ép. de κεντέω.</p></section></article>\n<article id=\"entry-dgp-22973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κενταύρειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2188 na letra κ · nº geral 22973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Centauro. 〈Κένταυρος〉</p></section></article>\n<article id=\"entry-dgp-22974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κενταυρίδης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2189 na letra κ · nº geral 22974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) = κενταύρειος.</p></section></article>\n<article id=\"entry-dgp-22975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κένταυρος, ου (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 2190 na letra κ · nº geral 22975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 masc. Centauro, monstro nascido de Ixíon e de Néfele 2 Centauro, ser híbrido, nascido de Centauro e dos cavalos da Tessália.</p></section></article>\n<article id=\"entry-dgp-22976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2191 na letra κ · nº geral 22976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κεντέω.</p></section></article>\n<article id=\"entry-dgp-22977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2192 na letra κ · nº geral 22977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κεντήσω, aor. ἐκέντησα, perf. desus.; pas. aor. ἐκεντήθην, perf. κεκέντημαι) 1 enterrar o aguilhão em, ac.; estimular com um aguilhão; espicaçar: κ. ἵππον hom. aguilhoar um cavalo 2 (inseto) atravessar com um aguilhão; picar 3 (planta) ferir; espetar 4 atravessar como se fosse um aguilhão; picar: κ. τινὰ τὸν ὀφθαλμόν arr. picar (com agulha) o olho de alguém (em cirurgia) 5 ferir: τῷ λιμῷ κεντούμενος alcífr. aguilhoado pela fome 6 praticar o ato sexual.</p></section></article>\n<article id=\"entry-dgp-22978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντητήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2193 na letra κ · nº geral 22978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 objeto para perfurar 2 sovela 3 agulha.</p></section></article>\n<article id=\"entry-dgp-22979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντουρίων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2194 na letra κ · nº geral 22979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. centurião. [lat.]</p></section></article>\n<article id=\"entry-dgp-22980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντρηνεκής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2195 na letra κ · nº geral 22980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impelido pelo aguilhão. 〈κέντρον, ἐνεγκεῖν〉</p></section></article>\n<article id=\"entry-dgp-22981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2196 na letra κ · nº geral 22981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aguilhoar; picar. 〈κέντρον〉</p></section></article>\n<article id=\"entry-dgp-22982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντρίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2197 na letra κ · nº geral 22982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de serpente. 〈κέντρον〉</p></section></article>\n<article id=\"entry-dgp-22983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντρίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2198 na letra κ · nº geral 22983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espécie de peixe 2 espécie de serpente. 〈κέντρον〉</p></section></article>\n<article id=\"entry-dgp-22984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντροδάλητις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2199 na letra κ · nº geral 22984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) dór. que atormenta com um aguilhão; pungente. 〈κέντρον, δηλέω〉</p></section></article>\n<article id=\"entry-dgp-22985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέντρον, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2200 na letra κ · nº geral 22985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aguilhão (para impelir animais) 2 aguilhão como estímulo moral; acicate 3 emblema de soberania 4 aguilhão (da dor, do desejo) 5 aguilhão de um animal; ferrão 6 esporão de galo 7 chicote munido de pregos (instrumento de tortura) 8 espinho do porco-espinho 9 ponta de lança 10 chaveta; cavilha 11 centro de uma circunferência 12 ponto fixo em torno do qual gira o compasso 13 Astron. ponto cardeal 14 nó (na madeira, na pedra).</p></section></article>\n<article id=\"entry-dgp-22986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2201 na letra κ · nº geral 22986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prover de aguilhão 2 picar com um aguilhão 3 pôr no centro; centralizar ♦ pas. 4 Astron. ocupar um ponto cardeal. 〈κέντρον〉</p></section></article>\n<article id=\"entry-dgp-22987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντρωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2202 na letra κ · nº geral 22987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 provido de aguilhão 2 munido de pregos pontiagudos. 〈κεντρόω〉</p></section></article>\n<article id=\"entry-dgp-22988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεντυρίων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2203 na letra κ · nº geral 22988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κεντουρίων.</p></section></article>\n<article id=\"entry-dgp-22989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέντωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 2204 na letra κ · nº geral 22989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que pica com aguilhão 2 que aguilhoa; pungente. 〈κεντέω〉</p></section></article>\n<article id=\"entry-dgp-22990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κένωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2205 na letra κ · nº geral 22990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espaço vazio; o vazio 2 Medic. evacuação; purgação 3 Filos. falta; inexistência 4 crist. o esvaziar-se; humilhação. 〈κενόω〉</p></section></article>\n";
